    this.boundingBox = dvReader.readBBox();
    this.centroidX = Math.toIntExact(dvReader.readVLong() + Integer.MIN_VALUE);
    this.centroidY = Math.toIntExact(dvReader.readVLong() + Integer.MIN_VALUE);

